@Composable fun PrimaryButton(text: String, enabled: Boolean = true, onClick: () -> Unit) { Button(onClick, Modifier.fillMaxWidth().height(56.dp), enabled, shape = RoundedCornerShape(Corners.small), colors = ButtonDefaults.buttonColors(containerColor = AppColors.Purple, disabledContainerColor = AppColors.PurpleSoft.copy(.55f))) { Text(text, fontWeight = FontWeight.Bold) } }
@Composable fun PinDots(count: Int, error: Boolean = false, emptyColor: Color = AppColors.Divider, filledColor: Color = AppColors.Purple) { Row(horizontalArrangement = Arrangement.spacedBy(14.dp)) { repeat(4) { Box(Modifier.size(18.dp).clip(CircleShape).background(if (it < count) if (error) MaterialTheme.colorScheme.error else filledColor else emptyColor)) } } }
@Composable fun NumericPinKeyboard(onDigit: (Int) -> Unit, onDelete: () -> Unit, highContrastDark: Boolean = false) { Column(verticalArrangement = Arrangement.spacedBy(12.dp)) { (1..9).chunked(3).forEach { row -> Row(Modifier.fillMaxWidth(), Arrangement.spacedBy(12.dp)) { row.forEach { n -> OutlinedButton({ onDigit(n) }, Modifier.weight(1f).height(64.dp), shape = RoundedCornerShape(Corners.small), colors = if (highContrastDark) ButtonDefaults.outlinedButtonColors(containerColor = AppColors.Card, contentColor = Color.White) else ButtonDefaults.outlinedButtonColors(), border = if (highContrastDark) BorderStroke(1.dp, Color(0xFF475569)) else null) { Text("$n", fontSize = 22.sp, fontWeight = FontWeight.Bold) } } } }; Row(Modifier.fillMaxWidth(), Arrangement.spacedBy(12.dp)) { Spacer(Modifier.weight(1f)); OutlinedButton({ onDigit(0) }, Modifier.weight(1f).height(64.dp), shape = RoundedCornerShape(Corners.small), colors = if (highContrastDark) ButtonDefaults.outlinedButtonColors(containerColor = AppColors.Card, contentColor = Color.White) else ButtonDefaults.outlinedButtonColors(), border = if (highContrastDark) BorderStroke(1.dp, Color(0xFF475569)) else null) { Text("0", fontSize = 22.sp, fontWeight = FontWeight.Bold) }; IconButton(onDelete, Modifier.weight(1f).height(64.dp)) { Icon(Icons.AutoMirrored.Filled.Backspace, "Borrar", tint = if (highContrastDark) Color(0xFFCBD5E1) else LocalContentColor.current) } } } }
@Composable fun UsageProgressCircle(usage: DailyUsage) { val current = usage.currentMinutes; val expected = usage.expectedMinutes; Box(Modifier.size(220.dp), Alignment.Center) { Canvas(Modifier.fillMaxSize()) { drawArc(Color.White.copy(.22f), -90f, 360f, false, style = Stroke(14.dp.toPx(), cap = StrokeCap.Round)); if (current != null && expected != null) drawArc(AppColors.PurpleSoft, -90f, 360f * (current.toFloat() / expected.coerceAtLeast(1)).coerceAtMost(1f), false, style = Stroke(14.dp.toPx(), cap = StrokeCap.Round)) }; Text(current?.let { "${it / 60} h ${it % 60} min" } ?: "Sin datos", color = Color.White, fontSize = 32.sp, fontWeight = FontWeight.Bold) } }
@Composable fun UsageAppRow(app: AppUsage, maxMinutes: Int) { Column(verticalArrangement = Arrangement.spacedBy(5.dp)) { Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) { Text(app.icon, fontSize = 20.sp); Spacer(Modifier.width(8.dp)); Text(app.name, Modifier.weight(1f), color = Color.White, fontWeight = FontWeight.Bold); Text("${app.minutes}m", color = Color.White.copy(.75f)) }; LinearProgressIndicator({ app.minutes.toFloat() / maxMinutes.coerceAtLeast(1) }, Modifier.fillMaxWidth().height(7.dp).clip(CircleShape), color = when(app.name) { "YouTube Kids" -> Color(0xFFEF4444); "Roblox" -> Color(0xFF8B5CF6); else -> Color(0xFF10B981) }, trackColor = Color.White.copy(.18f)) } }
@Composable fun MetricCard(title: String, value: String, detail: String, accent: Color = Color.White) { Card(Modifier.fillMaxWidth().heightIn(min = 150.dp), colors = CardDefaults.cardColors(containerColor = AppColors.Card), shape = RoundedCornerShape(Corners.small)) { Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) { Text(title.uppercase(), fontSize = 12.sp, color = Color(0xFFB8C4D8), fontWeight = FontWeight.Bold); Text(value, fontSize = 22.sp, lineHeight = 26.sp, color = accent, fontWeight = FontWeight.Bold); Text(detail, color = Color(0xFFCBD5E1), fontSize = 13.sp, lineHeight = 18.sp) } } }
